t.script:
(function () {
    const campo = document.getElementById("pt-codigo");
    if (!campo) { return; }
    const tela = document.getElementById("pt");
    let volta = null;
    campo.addEventListener("keydown", async (ev) => {
        if (ev.key !== "Enter" || !campo.value.trim()) { return; }
        const codigo = campo.value.trim();
        campo.value = "";
        try {
            const r = await fetch("/boteco/portaria/validar", {
                method: "POST", credentials: "same-origin",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { codigo } }),
            });
            const dados = (await r.json()).result || { cor: "vermelho", titulo: "Erro", detalhe: "" };
            tela.dataset.cor = dados.cor;
            document.getElementById("pt-titulo").textContent = dados.titulo;
            document.getElementById("pt-detalhe").textContent = dados.detalhe || "";
        } catch (e) {
            tela.dataset.cor = "vermelho";
            document.getElementById("pt-titulo").textContent = "Sem conexão";
        }
        clearTimeout(volta);
        volta = setTimeout(() => {
            tela.dataset.cor = "cinza";
            document.getElementById("pt-titulo").textContent = "Bipe a comanda";
            document.getElementById("pt-detalhe").textContent = "";
        }, 6000);
        campo.focus();
    });
    document.addEventListener("click", () => campo.focus());
})();
